const LanguageContext = createContext<{ language: Language; setLanguage: (value: Language) => void; t: (key: keyof typeof languageCopy.ar) => string } | null>(null);
function useLanguage() { const context = useContext(LanguageContext); if (!context) throw new Error("Language context is unavailable"); return context; }
function CalendarBar() { const { language, t } = useLanguage(); const [now, setNow] = useState(() => new Date()); useEffect(() => { const timer = window.setInterval(() => setNow(new Date()), 60_000); return () => window.clearInterval(timer); }, []); const date = new Intl.DateTimeFormat(language === "ar" ? "ar-YE" : "en-YE", { weekday: "long", day: "numeric", month: "long", year: "numeric" }).format(now); const hijri = new Intl.DateTimeFormat("ar-SA-u-ca-islamic", { day: "numeric", month: "long", year: "numeric" }).format(now); return <div className="calendar-bar" aria-label={`${t("today")}: ${date}`}><CalendarDays size={15} aria-hidden="true" /><span>{date}</span><i aria-hidden="true" /> <span>{hijri}</span></div>; }
function PinchZoomHandler() { useEffect(() => { let initialDistance = 0; let currentScale = 1; const getDistance = (touches: TouchList) => { const dx = touches[0].clientX - touches[1].clientX; const dy = touches[0].clientY - touches[1].clientY; return Math.sqrt(dx * dx + dy * dy); }; const handleTouchStart = (e: TouchEvent) => { if (e.touches.length === 2) { initialDistance = getDistance(e.touches); } }; const handleTouchMove = (e: TouchEvent) => { if (e.touches.length === 2 && initialDistance > 0) { e.preventDefault(); const currentDistance = getDistance(e.touches); const scaleChange = currentDistance / initialDistance; currentScale = Math.max(1, Math.min(2, scaleChange)); document.documentElement.style.setProperty("--access-scale", String(currentScale)); document.documentElement.style.setProperty("--access-image-scale", String(1 + (currentScale - 1) * .75)); } }; const handleTouchEnd = () => { initialDistance = 0; if (currentScale > 1) { localStorage.setItem("vipyemen-text-scale", String(currentScale)); } }; document.addEventListener("touchstart", handleTouchStart, { passive: true }); document.addEventListener("touchmove", handleTouchMove, { passive: false }); document.addEventListener("touchend", handleTouchEnd, { passive: true }); return () => { document.removeEventListener("touchstart", handleTouchStart); document.removeEventListener("touchmove", handleTouchMove); document.removeEventListener("touchend", handleTouchEnd); }; }, []); return null; }
function LanguageRuntime({ children }: { children: React.ReactNode }) { const [language, setLanguage] = useState<Language>(() => { const requested = new URLSearchParams(window.location.search).get("lang"); return requested === "en" || requested === "ar" ? requested : (localStorage.getItem("vipyemen-language") as Language) || "ar"; }); useEffect(() => { document.documentElement.lang = language; document.documentElement.dir = language === "ar" ? "rtl" : "ltr"; document.body.dataset.language = language; localStorage.setItem("vipyemen-language", language); }, [language]); const t = (key: keyof typeof languageCopy.ar) => languageCopy[language][key]; return <LanguageContext.Provider value={{ language, setLanguage, t }}><CalendarBar /><PinchZoomHandler />{children}</LanguageContext.Provider>; }

