type Ad = { id: number; title: string; message: string; linkUrl: string | null; status: "draft" | "scheduled" | "published" | "paused" | "expired"; currentStatus?: "draft" | "scheduled" | "published" | "paused" | "expired"; startsAt: Date; endsAt: Date; priority: number };
type AdStatus = Ad["status"];
const adStatusLabel: Record<AdStatus, string> = { draft: "مسودة", scheduled: "مجدول", published: "منشور", paused: "متوقف", expired: "منتهي" };
function getAdDisplayState(ad: Ad): AdStatus { if (ad.currentStatus) return ad.currentStatus; if (ad.status === "draft" || ad.status === "paused") return ad.status; const now = Date.now(); if (new Date(ad.endsAt).getTime() <= now) return "expired"; if (new Date(ad.startsAt).getTime() > now) return "scheduled"; return "published"; }
function toLocalDateTimeValue(value: Date | string) { const date = new Date(value); const offset = date.getTimezoneOffset() * 60000; return new Date(date.getTime() - offset).toISOString().slice(0, 16); }

function AnnouncementBar() {
  const { data: ads = [] } = trpc.advertisements.active.useQuery(undefined, { staleTime: 60_000, refetchInterval: 60_000 });
  const { language } = useLanguage();
  const fallback = language === "ar" ? { title: "مرحبًا بكم في ViP Yemen", message: "منصتكم الشاملة: تسويقية · خدمية · تقنية — كل الأمنيات بين يديك بثقة ومصداقية ومهنية" } : { title: "Welcome to ViP Yemen", message: "Your all-in-one marketing, service, and technology platform — opportunity within reach with trust and professionalism" };
  const items = ads.length ? ads : [{ id: 0, title: fallback.title, message: fallback.message, linkUrl: null, status: "published" as const, startsAt: new Date(), endsAt: new Date(Date.now() + 86_400_000), priority: 0 }];
  const renderItem = (ad: { id: number; title: string; message: string; linkUrl: string | null; status?: string; startsAt: Date; endsAt: Date; priority: number }, key: string) => <span className="announcement-item" key={key}><Megaphone size={15} aria-hidden="true" /><strong>{ad.title}</strong><span>{ad.message}</span>{ad.linkUrl ? <a href={ad.linkUrl} target="_blank" rel="noreferrer">{language === "ar" ? "التفاصيل" : "Details"} <ArrowLeft size={13} /></a> : null}</span>;
  return <aside className="announcement-bar" aria-label={language === "ar" ? "الإعلانات النشطة" : "Active announcements"}><div className="announcement-track" aria-hidden="false">{items.map((ad) => renderItem(ad, `a-${ad.id}`))}{items.map((ad) => renderItem(ad, `b-${ad.id}`))}</div></aside>;
}

