function ThemeRuntime({ children }: { children: React.ReactNode }) {
  const { data: themes = [] } = trpc.siteContent.publishedThemes.useQuery(undefined, { refetchInterval: 15000 });
  useEffect(() => {
    const config = themes[0]?.config as { primary?: string; accent?: string; background?: string; foreground?: string } | undefined;
    if (!config) return;
    const root = document.documentElement;
    const previous = { primary: root.style.getPropertyValue("--navy"), accent: root.style.getPropertyValue("--yellow"), background: root.style.getPropertyValue("--paper"), foreground: root.style.getPropertyValue("--ink") };
    if (config.primary) root.style.setProperty("--navy", config.primary);
    if (config.accent) root.style.setProperty("--yellow", config.accent);
    if (config.background) root.style.setProperty("--paper", config.background);
    if (config.foreground) root.style.setProperty("--ink", config.foreground);
    return () => { root.style.setProperty("--navy", previous.primary); root.style.setProperty("--yellow", previous.accent); root.style.setProperty("--paper", previous.background); root.style.setProperty("--ink", previous.foreground); };
  }, [themes]);
  return <>{children}</>;
}

