const readImageDataUrl = (file: File) => new Promise<string>((resolve, reject) => { const reader = new FileReader(); reader.onload = () => resolve(String(reader.result)); reader.onerror = () => reject(reader.error); reader.readAsDataURL(file); });

function DeveloperControls() {
  const utils = trpc.useUtils();
  const canManage = trpc.siteContent.canManage.useQuery();
  const assets = trpc.siteContent.adminAssets.useQuery(undefined, { enabled: canManage.data === true, refetchInterval: 10000 });
  const themes = trpc.siteContent.adminThemes.useQuery(undefined, { enabled: canManage.data === true, refetchInterval: 10000 });
  const sections = trpc.siteContent.adminSections.useQuery(undefined, { enabled: canManage.data === true, refetchInterval: 10000 });
  const revisions = trpc.siteContent.revisions.useQuery(undefined, { enabled: canManage.data === true, refetchInterval: 15000 });
  const restoreRevision = trpc.siteContent.restoreRevision.useMutation({ onSuccess: () => { utils.siteContent.adminAssets.invalidate(); utils.siteContent.adminThemes.invalidate(); utils.siteContent.adminSections.invalidate(); } });
  const createAsset = trpc.siteContent.createAsset.useMutation({ onSuccess: () => utils.siteContent.adminAssets.invalidate() });
  const updateAsset = trpc.siteContent.updateAsset.useMutation({ onSuccess: () => utils.siteContent.adminAssets.invalidate() });
  const createTheme = trpc.siteContent.createTheme.useMutation({ onSuccess: () => utils.siteContent.adminThemes.invalidate() });
  const activateTheme = trpc.siteContent.activateTheme.useMutation({ onSuccess: () => utils.siteContent.adminThemes.invalidate() });
  const createSection = trpc.siteContent.createSection.useMutation({ onSuccess: () => utils.siteContent.adminSections.invalidate() });
  const updateSection = trpc.siteContent.updateSection.useMutation({ onSuccess: () => utils.siteContent.adminSections.invalidate() });
  const submit = async (event: React.FormEvent<HTMLFormElement>, kind: "asset" | "theme" | "section") => {
    event.preventDefault();
    const form = new FormData(event.currentTarget);
    if (kind === "asset") { const file = form.get("assetFile"); const dataUrl = file instanceof File && file.size > 0 ? await readImageDataUrl(file) : undefined; createAsset.mutate({ kind: String(form.get("kind")) as "image" | "banner" | "icon", name: String(form.get("name")), url: String(form.get("url") || ""), dataUrl, altText: String(form.get("altText")), isPublished: form.get("isPublished") === "on" }); }
    if (kind === "theme") createTheme.mutate({ name: String(form.get("themeName")), config: { primary: String(form.get("primary")), accent: String(form.get("accent")), background: String(form.get("background")), foreground: String(form.get("foreground")) } });
    if (kind === "section") createSection.mutate({ slug: String(form.get("slug")), title: String(form.get("sectionTitle")), description: String(form.get("sectionDescription") || "") || undefined, sortOrder: Number(form.get("sortOrder") || 0), isPublished: form.get("sectionPublished") === "on" });
    event.currentTarget.reset();
  };
  if (canManage.isLoading) return <section className="admin-panel developer-controls"><div className="admin-loading">جارٍ التحقق من صلاحية أدوات المطور...</div></section>;
  if (!canManage.data) return <section className="admin-panel developer-controls developer-forbidden"><div className="empty-state"><ShieldCheck size={24} /><strong>أدوات المطور محجوبة</strong><span>هذه الأدوات متاحة لمالك المشروع فقط.</span></div></section>;
  return <section className="admin-panel developer-controls"><div className="panel-heading"><div><h2>أدوات المطور والمالك</h2><p>تحديث تلقائي للمعاينة كل 10 ثوانٍ، ولا تظهر هذه الأدوات إلا لمالك المشروع.</p></div><Code2 /></div><div className="developer-grid"><div><h3>إضافة أصل بصري</h3><form className="admin-form" onSubmit={event => submit(event, "asset")}><select name="kind" defaultValue="banner"><option value="banner">بنر</option><option value="image">صورة</option><option value="icon">أيقونة</option></select><input name="name" required placeholder="اسم الأصل" /><input name="url" placeholder="/manus-storage/... أو https://" /><input name="assetFile" type="file" accept="image/jpeg,image/png,image/webp" /><input name="altText" required placeholder="وصف بديل للصورة" /><label className="check-row"><input name="isPublished" type="checkbox" /> نشره بعد المراجعة في المعاينة العامة</label><button className="button button-primary" disabled={createAsset.isPending}>حفظ الأصل كمسودة أو نشره</button></form><div className="admin-list compact-list">{(assets.data || []).map(asset => <div className="admin-item" key={asset.id}><div className="asset-row"><img className="asset-preview" src={asset.url} alt={asset.altText} loading="lazy" /><div><strong>{asset.name}</strong><small>{asset.kind} · {asset.isPublished ? "منشور" : "مسودة — معاينة خاصة"}</small></div></div><button onClick={() => updateAsset.mutate({ id: asset.id, isPublished: !asset.isPublished })}>{asset.isPublished ? "إيقاف" : "نشر"}</button></div>)}</div></div><div><h3>الثيمات: مسودة / معاينة / نشر</h3><form className="admin-form" onSubmit={event => submit(event, "theme")}><input name="themeName" required placeholder="اسم الثيم" /><div className="color-row"><input name="primary" defaultValue="#102A43" pattern="^#[0-9a-fA-F]{6}$" aria-label="اللون الأساسي" /><input name="accent" defaultValue="#F3B71B" pattern="^#[0-9a-fA-F]{6}$" aria-label="لون التمييز" /></div><div className="color-row"><input name="background" defaultValue="#FFFDF8" pattern="^#[0-9a-fA-F]{6}$" aria-label="لون الخلفية" /><input name="foreground" defaultValue="#102A43" pattern="^#[0-9a-fA-F]{6}$" aria-label="لون النص" /></div><button className="button button-primary" disabled={createTheme.isPending}>حفظ الثيم</button></form><div className="admin-list compact-list">{(themes.data || []).map(theme => <div className="admin-item" key={theme.id}><div className="theme-preview" style={{ backgroundColor: String((theme.config as Record<string, unknown>).background || "#FFFDF8"), color: String((theme.config as Record<string, unknown>).foreground || "#102A43"), borderColor: String((theme.config as Record<string, unknown>).accent || "#F3B71B") }}><strong>{theme.name}</strong><small>{theme.isActive ? "منشور ونشط" : "مسودة — معاينة"}</small></div><button onClick={() => activateTheme.mutate({ id: theme.id })}>{theme.isActive ? "نشط حاليًا" : "معاينة ثم نشر"}</button></div>)}</div></div><div><h3>الأقسام: مسودة / معاينة / نشر</h3><form className="admin-form" onSubmit={event => submit(event, "section")}><input name="slug" required pattern="^[a-z0-9-]{2,100}$" placeholder="slug مثل: services-new" /><input name="sectionTitle" required placeholder="عنوان القسم" /><textarea name="sectionDescription" placeholder="وصف القسم" /><input name="sortOrder" type="number" min="0" defaultValue="10" placeholder="الترتيب" /><label className="check-row"><input name="sectionPublished" type="checkbox" defaultChecked /> نشر القسم</label><button className="button button-primary" disabled={createSection.isPending}>إضافة القسم</button></form><div className="admin-list compact-list">{(sections.data || []).map(section => <div className="admin-item" key={section.id}><div><strong>{section.title}</strong><small>{section.slug} · {section.isPublished ? "منشور" : "مسودة — معاينة"} · ترتيب {section.sortOrder}</small>{section.description ? <p>{section.description}</p> : null}</div><div className="section-actions"><input type="number" min="0" defaultValue={section.sortOrder} aria-label={`ترتيب ${section.title}`} onBlur={event => { const next = Number(event.currentTarget.value); if (Number.isInteger(next) && next >= 0 && next !== section.sortOrder) updateSection.mutate({ id: section.id, sortOrder: next }); }} /><button onClick={() => updateSection.mutate({ id: section.id, isPublished: !section.isPublished })}>{section.isPublished ? "إخفاء" : "نشر"}</button><details className="section-edit"><summary>تحرير</summary><form onSubmit={event => { event.preventDefault(); const form = new FormData(event.currentTarget); updateSection.mutate({ id: section.id, slug: String(form.get("slug")), title: String(form.get("title")), description: String(form.get("description") || "") || undefined, sortOrder: Number(form.get("sortOrder") || 0), isPublished: form.get("isPublished") === "on" }); }}><input name="slug" defaultValue={section.slug} pattern="^[a-z0-9-]{2,100}$" required /><input name="title" defaultValue={section.title} required /><textarea name="description" defaultValue={section.description || ""} /><input name="sortOrder" type="number" min="0" defaultValue={section.sortOrder} /><label className="check-row"><input name="isPublished" type="checkbox" defaultChecked={!!section.isPublished} /> نشر</label><button type="submit">حفظ</button></form></details></div></div>)}</div></div></div><div className="revision-panel"><div><h3>سجل النسخ والتراجع</h3><p>يمكن استرجاع آخر 50 لقطة محفوظة. الاسترجاع لا يحذف البيانات السابقة.</p></div><div className="revision-list">{(revisions.data || []).map(revision => <div className="revision-row" key={revision.id}><span>{revision.entityType} · {revision.action} · {new Date(revision.createdAt).toLocaleString("ar-YE")}</span><button onClick={() => { if (window.confirm("استرجاع هذه اللقطة؟")) restoreRevision.mutate({ id: revision.id }); }} disabled={restoreRevision.isPending}>استرجاع</button></div>)}</div></div></section>;
}

function VipChatbot() { const [open, setOpen] = useState(false); const { language } = useLanguage(); return <div className="vip-chatbot"><button className="vip-chatbot-btn" onClick={() => setOpen(!open)} aria-label="مساعد VIP الذكي"><img src="/images/vip-logo.svg" alt="VIP" className="vip-chatbot-logo" /></button>{open ? <div className="vip-chatbot-panel"><div className="vip-chatbot-header"><img src="/images/vip-logo.svg" alt="VIP" style={{width:20,height:20}} /><span>{language === "ar" ? "مساعد VIP الذكي" : "VIP Smart Assistant"}</span><button onClick={() => setOpen(false)} aria-label="إغلاق"><X size={16} /></button></div><div className="vip-chatbot-body"><div className="vip-chatbot-msg bot"><img src="/images/vip-logo.svg" alt="VIP" style={{width:16,height:16}} /><span>{language === "ar" ? "مرحبًا! أنا مساعد VIP الذكي. كيف يمكنني مساعدتك اليوم؟" : "Hello! I'm the VIP Smart Assistant. How can I help you today?"}</span></div><div className="vip-chatbot-options"><a href="https://wa.me/967711780999" target="_blank" rel="noreferrer" className="vip-chatbot-option"><MessageCircle size={14} /> {language === "ar" ? "تواصل عبر واتساب" : "WhatsApp"}</a><a href="#submit" onClick={() => setOpen(false)} className="vip-chatbot-option"><Send size={14} /> {language === "ar" ? "أرسل طلب" : "Send request"}</a><a href="#services" onClick={() => setOpen(false)} className="vip-chatbot-option"><Globe2 size={14} /> {language === "ar" ? "استكشف الخدمات" : "Explore services"}</a></div></div></div> : null}</div>; }

class ErrorBoundary extends Component<{ children: ReactNode }, { hasError: boolean; error: string }> {
  constructor(props: { children: ReactNode }) {
    super(props);
    this.state = { hasError: false, error: "" };
  }
  static getDerivedStateFromError(error: Error) {
    return { hasError: true, error: error.message };
  }
  render() {
    if (this.state.hasError) {
      return (
        <div style={{ minHeight: "100vh", display: "flex", alignItems: "center", justifyContent: "center", background: "#0B2034", color: "white", fontFamily: "IBM Plex Sans Arabic, sans-serif", padding: "20px", textAlign: "center" }}>
          <div style={{ maxWidth: 480 }}>
            <img src="/images/vip-logo.svg" alt="ViP" style={{ width: 60, height: 60, marginBottom: 20 }} />
            <h2 style={{ marginBottom: 12 }}>حدث خطأ غير متوقع</h2>
            <p style={{ color: "rgba(255,255,255,.7)", marginBottom: 24 }}>يمكنك المحاولة مرة أخرى أو العودة للصفحة الرئيسية</p>
            <button onClick={() => { this.setState({ hasError: false, error: "" }); window.location.href = "/"; }} style={{ background: "#F3B71B", color: "#0B2034", border: "none", padding: "12px 24px", borderRadius: 8, fontWeight: 700, cursor: "pointer", fontSize: 14 }}>العودة للرئيسية</button>
          </div>
        </div>
      );
    }
    return this.props.children;
  }
}

function AutoUpdateChecker() {
  useEffect(() => {
    let lastVersion = localStorage.getItem("vipyemen-version") || "1.7.0";
    const checkUpdate = async () => {
      try {
        const response = await fetch("/manifest.json", { cache: "no-cache" });
        if (response.ok) {
          const manifest = await response.json();
          const currentVersion = manifest.version || "1.7.0";
          if (currentVersion !== lastVersion) {
            localStorage.setItem("vipyemen-version", currentVersion);
            lastVersion = currentVersion;
          }
        }
      } catch {
        // Silently fail - updates will load on next page refresh
      }
    };
    // Check every 5 minutes
    const interval = window.setInterval(checkUpdate, 5 * 60 * 1000);
    checkUpdate();
    return () => window.clearInterval(interval);
  }, []);
  return null;
}

function NotFound() { return <div className="not-found"><h1>الصفحة غير موجودة</h1><Link href="/">العودة للرئيسية</Link></div>; }
export default function App() { return <ErrorBoundary><LanguageRuntime><ThemeRuntime><AutoUpdateChecker /><Switch><Route path="/" component={Home} /><Route path="/admin" component={AdminLogin} /><Route path="/admin/dashboard" component={AdminDashboardPage} /><Route path="/departments/employment" component={EmploymentSection} /><Route path="/departments/real-estate" component={RealEstateSection} /><Route path="/departments/e-marketing" component={EMarketingSection} /><Route path="/departments/software" component={SoftwareDeptSection} /><Route path="/departments/listings" component={DepartmentListings} /><Route component={NotFound} /></Switch><VipChatbot /></ThemeRuntime></LanguageRuntime></ErrorBoundary>; }
